func FilesLoadMessages(values []Files, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !FilesLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// MeterReset restores Meter's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MeterReset(value *Meter) {
	TicksReset(&value.Ticks)
	value.TicksPresent = false
	value.TopAt = 0
	value.TopPct = 0.0
	FilesReset(&value.Files)
	value.FilesPresent = false
}

func MeterMeasureBody(value *Meter, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !MeterSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func MeterMeasure(value *Meter) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !MeterSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func MeterMeasureReason(value *Meter) (int64, error) {
	size := MeterMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
