func MeterSaveMessageBody(w *TableMessageWriter, value *Meter) bool {
	{
		if value.TicksPresent {
			if true {
				w.Put(80, TableMessageRefBitsHere)
				if !TicksSaveMessageBody(w, &value.Ticks) {
					return false
				}
			}
		}
	}
	{
		if value.TopAt != 0 {
			w.Put(23, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 5, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.TopAt), uint64(0))
		}
	}
	{
		if value.TopPct != 0.0 {
			w.Put(81, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 11, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, math.Float64bits(value.TopPct), uint64(0))
		}
	}
	{
		if value.FilesPresent {
			if true {
				w.Put(82, TableMessageRefBitsHere)
				if !FilesSaveMessageBody(w, &value.Files) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func MeterMeasureMessages(values []*Meter, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !MeterSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func MeterSaveMessages(values []*Meter, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !MeterSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
