func BeatLoadMessages(values []Beat, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !BeatLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ReaderHoldReset restores ReaderHold's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReaderHoldReset(value *ReaderHold) {
	value.Away = false
	value.Retired = false
	value.At = 0
	clear(value.By[:])
	value.ByLength = 0
	value.Held = false
	clear(value.Reason[:])
	value.ReasonLength = 0
	value.GiveBack = false
}

func ReaderHoldMeasureBody(value *ReaderHold, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ReaderHoldSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

