// LaneWaitReset restores LaneWait's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LaneWaitReset(value *LaneWait) {
	clear(value.Who[:])
	value.WhoLength = 0
	value.Since = 0
	value.Seen = 0
}

