func SeatChangeLoadMessages(values []SeatChange, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !SeatChangeLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ServerRecordReset restores ServerRecord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ServerRecordReset(value *ServerRecord) {
	clear(value.Actor[:])
	value.ActorLength = 0
	value.At = 0
	clear(value.Version[:])
	value.VersionLength = 0
	clear(value.Commit[:])
	value.CommitLength = 0
	value.Started = 0
	value.Land = false
	value.Pid = 0
	clear(value.Host[:])
	value.HostLength = 0
}

func ServerRecordMeasureBody(value *ServerRecord, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ServerRecordSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ServerRecordMeasure(value *ServerRecord) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ServerRecordSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ServerRecordMeasureReason(value *ServerRecord) (int64, error) {
	size := ServerRecordMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
