// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func MeterFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(MeterFixedLayout)) + count*MeterFixedRecordBytes
}

func MeterFixedSave(values []Meter, buffer []byte) int64 {
	need := MeterFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], MeterFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(MeterFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], MeterFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(MeterFixedLayout):]
	for k := range values {
		tableFixedPut64(at, MeterFixedHash)
		clear(at[8 : 8+MeterFixedBodyBytes])
		MeterFixedWriteBody(at[8:], &values[k])
		at = at[MeterFixedRecordBytes:]
	}
	return need
}

